 @Test void orderDependentCashFlowIsRedactedIncludingAsOfAcrossProjections()throws Exception {
  getJson("/v2/positions","owner",200);var original=repository.list(PortfolioRepository.Kind.CONSTRUCTION,Set.of(account)).stream().filter(d->PortfolioJson.leaves(d.value().path("composition")).getFirst().path("kind").asText().equals("LONG_SHARES")).findFirst().orElseThrow();var position=repository.get(original.value().at("/position/href").asText()).orElseThrow();var c=original.value().deepCopy();String cid=UUID.randomUUID().toString(),curi="/v2/constructions/"+cid;c.put("id",cid).put("changeKind","EVIDENCE_REINTERPRETATION");c.set("self",PortfolioJson.link(curi));c.set("predecessor",original.value().path("self"));var leaf=PortfolioJson.leaves(c.path("composition")).getFirst();var basis=(com.fasterxml.jackson.databind.node.ObjectNode)leaf.at("/allocation/basis");basis.put("value","25").put("status","QUALIFIED").put("method","SYNTHETIC_ORDER_QUALIFIED_SECURITY_SPECIMEN");basis.set("dependencies",PortfolioJson.array().add("ORDER_EVIDENCE"));String witness=UUID.randomUUID().toString();byte[] witnessBytes="{\"synthetic\":true,\"fills\":[{\"basis\":\"25\",\"at\":\"2026-10-05T12:34:56Z\"}]}".getBytes(java.nio.charset.StandardCharsets.UTF_8);try(var connection=repository.connection();var query=connection.prepareStatement("INSERT INTO brokerage_artifact VALUES (?,?,?,?,?,?,?)")){query.setString(1,account);query.setString(2,witness);query.setString(3,BrokerageArtifacts.sha(witnessBytes));query.setString(4,"application/json");query.setInt(5,witnessBytes.length);query.setBytes(6,witnessBytes);query.setString(7,"2026-10-05T12:35:00Z");query.executeUpdate();}var source=PortfolioJson.source(account,witness,"/fills/0","2026-10-05","2026-10-05T12:34:56Z","SYNTHETIC");source.put("requiredCapability","account.orders.read:"+account);basis.set("evidence",PortfolioJson.array().add(source));((com.fasterxml.jackson.databind.node.ObjectNode)leaf.get("allocation")).put("basisMethod","BROKER_ATTRIBUTED");var updated=position.value().deepCopy();updated.put("state","OPEN");var lifecycle=(com.fasterxml.jackson.databind.node.ObjectNode)updated.path("stateEvidence");lifecycle.put("status","ESTABLISHED").put("establishedAt","2026-10-05T12:34:56Z").put("completeness","SCOPED_ACCEPTED");lifecycle.set("evidence",PortfolioJson.array().add(source));updated.set("currentConstruction",PortfolioJson.link(curi));try(var tx=repository.connection()){tx.setAutoCommit(false);repository.put(tx,new PortfolioRepository.Document(PortfolioRepository.Kind.CONSTRUCTION,curi,account,c,position.snapshot(),position.sourceKey()));repository.put(tx,new PortfolioRepository.Document(position.kind(),position.uri(),account,updated,position.snapshot(),position.sourceKey()));tx.commit();}
  var authorized=getJson(position.uri(),"owner",200);assertThat(authorized.at("/evaluation/openingCashFlow/value").isNull()).isFalse();
  var restricted=getJson(position.uri(),"position",200);assertThat(restricted.at("/stateEvidence/establishedAtAccess").asText()).isEqualTo("REDACTED");assertThat(restricted.at("/stateEvidence/establishedAt").isNull()).isTrue();assertThat(restricted.at("/stateEvidence/evidence")).hasSize(1);assertThat(restricted.at("/evaluation/openingCashFlow/status").asText()).isEqualTo("REDACTED");assertThat(restricted.at("/evaluation/openingCashFlow/asOf").isNull()).isTrue();assertThat(restricted.toString()).doesNotContain("2026-10-05T12:34:56Z");
  for(String projection:List.of("summary","expanded")){var result=getJson("/v2/positions?projection="+projection,"position",200);var match=new java.util.ArrayList<JsonNode>();result.path("items").forEach(n->{if(n.path("id").equals(updated.path("id")))match.add(n);});assertThat(match).hasSize(1);assertThat(match.getFirst().at("/evaluation/openingCashFlow/asOf").isNull()).isTrue();assertThat(match.getFirst().at("/evaluation/openingCashFlow/value").isNull()).isTrue();}
 }
 @Test void incompleteSourceScopeQualifiesCurrentPositionAndConstructionWithoutInventingQuantities()throws Exception{
  var artifacts=new BrokerageArtifacts(db.getConnection().getMetaData().getURL(),mapper,new PositionReadService(db,mapper));var imported=artifacts.ingest(account,"partial-quantity.csv","POSITIONS",PositionsTest.csv(PositionsTest.BODY+"A1,Test PTS,ETFs,SPY,Additional units not reported,,--,--,Cash\n","Oct-06-2026").getBytes(java.nio.charset.StandardCharsets.UTF_8),UUID.randomUUID().toString());assertThat(imported.status()).isEqualTo("ACCEPTED");getJson("/v2/positions","owner",200);String snapshot=new PortfolioSnapshots(repository).current(account).orElseThrow().snapshotId();
  var position=repository.list(PortfolioRepository.Kind.POSITION,Set.of(account)).stream().filter(p->snapshot.equals(p.snapshot())).filter(p->{try{return PortfolioJson.leaves(repository.get(p.value().at("/currentConstruction/href").asText()).orElseThrow().value().path("composition")).getFirst().path("kind").asText().equals("LONG_SHARES");}catch(Exception e){throw new RuntimeException(e);}}).findFirst().orElseThrow();
  var value=getJson(position.uri(),"owner",200);assertThat(value.at("/allocation/status").asText()).isEqualTo("UNKNOWN");assertThat(value.at("/evaluation/marketValue/status").asText()).isEqualTo("INCOMPLETE");assertThat(value.path("warnings").toString()).contains("HOLDING_RECONCILIATION_CONFLICT");var construction=getJson(position.value().at("/currentConstruction/href").asText(),"owner",200);var leaf=PortfolioJson.leaves(construction.path("composition")).getFirst();assertThat(leaf.at("/allocation/globalStatus").asText()).isEqualTo("UNKNOWN");assertThat(PortfolioJson.number(leaf.path("quantity"))).isPositive();assertThat(getJson(leaf.at("/allocation/holding/href").asText(),"owner",200).path("quantity").asText()).isEqualTo(leaf.path("quantity").asText());
 }

 @Test void directoryFailureUsesStructuredErrorsAndDoesNotBlockSharedModelReads()throws Exception{
  var unavailable=new AccountDirectory(db.getConnection().getMetaData().getURL()){@Override public java.util.List<AccountDirectory.Account> list()throws java.sql.SQLException{throw new java.sql.SQLException("synthetic directory unavailable");}};
  mvc=MockMvcBuilders.standaloneSetup(new PortfolioController(reads,TestAuthentication.auth("owner=user:account.positions.read:"+account+"|reference.read"),unavailable)).build();var failure=getJson("/v2/positions","owner",503);assertThat(failure.path("code").asText()).isEqualTo("CAPABILITY_UNAVAILABLE");getJson("/v2/constructions/models/COVERED_CALL/versions/1","owner",200);
 }

